ValidationRule.errorConditionFormula:
AND( RecordType.DeveloperName = "GDS", $Setup.EnableValidationRule__c.Flag_To_Prevent_TMC_VR_Fired__c = FALSE, ISCHANGED(Active__c), Active__c = FALSE,
OR(
NOT( OR( ISPICKVAL(GDS_Status__c , "New"), ISPICKVAL(GDS_Status__c , "Inactive"), ISBLANK(TEXT(GDS_Status__c)) ) ), AND( ISCHANGED(GDS_Status__c), OR( ISPICKVAL(GDS_Status__c , "New"), ISPICKVAL(GDS_Status__c , "Inactive"), ISBLANK(TEXT(GDS_Status__c)) ), ISPICKVAL(PRIORVALUE(GDS_Status__c),"Accepted") )
)
)
